UPDATE product_sku
spec_name = #{specName}, flavor = #{flavor}, package_size = #{packageSize}, price = #{price}, stock = #{stock}, image_url = #{imageUrl}, status = #{status}, update_time = NOW()
WHERE id = #{id}

UPDATE product_sku
SET stock = stock - #{quantity}, update_time = NOW()
WHERE id = #{id} AND status = 1 AND stock >= #{quantity}

UPDATE product_sku
SET stock = stock + #{quantity}, update_time = NOW()
WHERE id = #{id}
